    Rk_expr = calc_rootis(k)[pos]
    
    # 2) coerce into a true polynomial in x0…x_{k-1}
    var_names = [f'x{i}' for i in range(k)]
    PR = PolynomialRing(QQ, var_names)
    Rk_poly = PR(Rk_expr)

    # 3) build the SF‑ring over the same QQ
    SF = SymmetricFunctions(PR.base_ring())
    M  = SF.monomial()     # monomial basis
    E  = SF.elementary()   # elementary basis

    # 4) lift into monomials, then convert to elementary basis
    fs = M.from_polynomial(Rk_poly, k)  # element of the monomial basis
    fe = E(fs)                          # now in the elementary basis

    # 5) print your results
    print(f"\nk = {k}:")
    print(calc_fixed(k)[pos])
    print(factor_over_quadratic_field(k,pos=pos))
    print("  raw (in x_i):         ", Rk_poly.factor())
    print("  elementary‐basis form:", fe)
    print("\n")

